"""Build EN / IT / FR versions of the LindaLuna site from site/index.html.
Usage: python3 tools/build_i18n.py   (from the repository root)
Writes <out>/en/, <out>/it/, <out>/fr/ (index.html each). The root page is the language splash.
Luna's farewell stays in English everywhere, by design.
"""
import sys, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "src", "site.en.html")
out = sys.argv[1] if len(sys.argv) > 1 else ROOT

